div.script:
/* ============================================================
   SVG host shim
   The document is image/svg+xml, so it is parsed as XML and has
   no <body>. These three patches give the page back the DOM it
   expects, without touching the page's own logic.
   ============================================================ */
(function () {
  'use strict';

  var XHTML = 'http://www.w3.org/1999/xhtml';
  var root = document.getElementById('ghoul-root');

  /* 1. document.body -> the shell div that holds the page. */
  try {
    Object.defineProperty(document, 'body', {
      configurable: true,
      enumerable: true,
      get: function () { return root; }
    });
  } catch (e) {}

  /* 2. Elements made with document.createElement() have no namespace in an
        XML document: no CSS box, no iframe. Create them as XHTML instead. */
  var nativeCreate = Document.prototype.createElement;
  Document.prototype.createElement = function (name, options) {
    if (this === document) return this.createElementNS(XHTML, name);
    return nativeCreate.call(this, name, options);
  };

  /* 3. innerHTML parses as XML here and rejects ordinary HTML markup
        (<img>, <br>, unquoted attributes...). Parse it as HTML and import
        the resulting nodes instead. Reads still go to the native getter. */
  var nativeHTML = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
  if (nativeHTML && nativeHTML.get && nativeHTML.set) {
    Object.defineProperty(Element.prototype, 'innerHTML', {
      configurable: true,
      enumerable: nativeHTML.enumerable,
      get: function () { return nativeHTML.get.call(this); },
      set: function (markup) {
        var text = markup == null ? '' : String(markup);
        while (this.firstChild) this.removeChild(this.firstChild);
        if (!text) return;
        var parsed = new DOMParser().parseFromString(
          '<!doctype html><html><body>' + text + '</body></html>', 'text/html'
        );
        var child = parsed.body.firstChild;
        while (child) {
          this.appendChild(document.importNode(child, true));
          child = child.nextSibling;
        }
      }
    });
  }

  /* 4. The document itself cannot scroll, so PageDown/Space/Home/End/arrows
        would do nothing. Forward them to whichever scroll box is on screen. */
  function scrollTarget() {
    var active = document.activeElement;
    var menu = document.getElementById('menu');
    if (menu && !menu.hidden && active && menu.contains(active)) return null;
    var panic = document.getElementById('panic');
    if (panic && !panic.hidden) return panic.scrollHeight > panic.clientHeight ? panic : null;
    if (document.documentElement.classList.contains('is-playing')) return null;
    return document.getElementById('ghoul-page');
  }

  function typing(el) {
    if (!el || !el.tagName) return false;
    var tag = el.tagName.toLowerCase();
    return tag === 'input' || tag === 'textarea' || tag === 'select' || el.isContentEditable === true;
  }

  document.addEventListener('keydown', function (event) {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
    var target = event.target;
    if (typing(target)) return;
    var box = scrollTarget();
    if (!box) return;

    var step = Math.max(120, box.clientHeight - 80);
    var line = 48;
    var to;
    switch (event.key) {
      case 'PageDown': to = box.scrollTop + step; break;
      case 'PageUp': to = box.scrollTop - step; break;
      case 'ArrowDown': to = box.scrollTop + line; break;
      case 'ArrowUp': to = box.scrollTop - line; break;
      case 'Home': to = 0; break;
      case 'End': to = box.scrollHeight; break;
      case ' ':
        if (target.closest && target.closest('a, button, summary, label, [role="button"], [role="link"]')) return;
        to = box.scrollTop + (event.shiftKey ? -step : step);
        break;
      default: return;
    }
    event.preventDefault();
    box.scrollTop = to;
  }, { passive: false });

  window.__ghoulSvgHost = true;
})();

/* Each library page gets its own tab title before the catalogue even loads. */
(function () {
  try {
    var page = new URLSearchParams(window.location.search).get('page');
    if (page === 'noahs') document.title = "Noah's Tutoring — free browser games · Ghoulish";
  } catch (e) {}
})();

/* Boot script — runs before first paint so the panic screen, the tab cloak and
   the saved accent colour are already on screen. Nothing here touches the network. */
(function () {
  var root = document.documentElement;

  /* ---------------- accent colour ---------------- */

  var ACCENT_KEY = 'ghoul:accent';
  var DEFAULT_ACCENT = '#e0142b';

  function parseHex(hex) {
    var m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(hex || '').trim());
    if (!m) return null;
    var h = m[1];
    if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  }

  function mix(hex, toward, amount) {
    var a = parseHex(hex), b = parseHex(toward);
    if (!a || !b) return hex;
    var out = '#';
    for (var i = 0; i < 3; i++) {
      var v = Math.round(a[i] + (b[i] - a[i]) * amount);
      out += ('0' + Math.max(0, Math.min(255, v)).toString(16)).slice(-2);
    }
    return out;
  }

  function alpha(hex, a) {
    var c = parseHex(hex);
    return c ? 'rgba(' + c[0] + ', ' + c[1] + ', ' + c[2] + ', ' + a + ')' : hex;
  }

  function paintAccent(hex) {
    var accent = parseHex(hex) ? (hex.charAt(0) === '#' ? hex : '#' + hex) : DEFAULT_ACCENT;
    root.style.setProperty('--accent', accent);
    root.style.setProperty('--red', accent);
    root.style.setProperty('--red-2', mix(accent, '#ffffff', .32));
    root.style.setProperty('--red-deep', mix(accent, '#000000', .60));
    root.style.setProperty('--line-red', alpha(accent, .26));
    root.style.setProperty('--shadow-red', '0 24px 70px -32px ' + alpha(accent, .75));
    root.style.setProperty('--bg', mix(accent, '#05040a', .93));
    root.style.setProperty('--bg-soft', mix(accent, '#05040a', .90));
    root.style.setProperty('--panel', mix(accent, '#05040a', .87));
    root.style.setProperty('--panel-2', mix(accent, '#05040a', .84));
  }

  var storedAccent = null;
  try { storedAccent = localStorage.getItem(ACCENT_KEY); } catch (e) {}
  paintAccent(storedAccent || DEFAULT_ACCENT);

  /* ---------------- look & feel ---------------- */

  /* Applied before first paint so a custom font, density or backdrop never
     flashes the default first. The settings menu writes the same object. */

  var LOOK_KEY = 'ghoul:look';
  var LOOK_DEFAULTS = {
    font: 'cinzel', corners: 'round', density: 'cozy', ambience: 'full', motion: 'on',
    bg: '', name: '', tagline: '', spotlight: true, recent: true, how: true
  };
  var LOOK_ALLOWED = {
    font: ['cinzel', 'grotesk', 'serif', 'mono'],
    corners: ['round', 'sharp'],
    density: ['compact', 'cozy', 'large'],
    ambience: ['full', 'calm', 'off'],
    motion: ['on', 'off']
  };

  /* Only real image URLs (or a file sitting next to this one) reach CSS. */
  function safeImageUrl(value) {
    var url = String(value || '').trim();
    if (!url) return '';
    if (/^(https?:|data:image\/)/i.test(url)) {
      try { new URL(url); return url; } catch (e) { return ''; }
    }
    return /^[./\w%:@~?&()=-]+$/.test(url) ? url : '';
  }

  function cssUrl(url) {
    return url.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\r\n]/g, '');
  }

  function readLook() {
    var raw = null;
    try { raw = JSON.parse(localStorage.getItem(LOOK_KEY) || 'null'); } catch (e) {}
    var look = {};
    for (var key in LOOK_DEFAULTS) look[key] = LOOK_DEFAULTS[key];
    if (raw && typeof raw === 'object') {
      Object.keys(LOOK_ALLOWED).forEach(function (name) {
        if (LOOK_ALLOWED[name].indexOf(raw[name]) >= 0) look[name] = raw[name];
      });
      look.spotlight = raw.spotlight !== false;
      look.recent = raw.recent !== false;
      look.how = raw.how !== false;
      look.name = typeof raw.name === 'string' ? raw.name.slice(0, 18) : '';
      look.tagline = typeof raw.tagline === 'string' ? raw.tagline.slice(0, 70) : '';
      look.bg = safeImageUrl(raw.bg);
    }
    return look;
  }

  function paintLook(look) {
    Object.keys(LOOK_ALLOWED).forEach(function (key) {
      root.setAttribute('data-' + key, look[key]);
    });
    root.setAttribute('data-home-spotlight', look.spotlight === false ? 'off' : 'on');
    root.setAttribute('data-home-recent', look.recent === false ? 'off' : 'on');
    root.setAttribute('data-home-how', look.how === false ? 'off' : 'on');
    if (look.bg) {
      root.style.setProperty('--bg-image', 'url("' + cssUrl(look.bg) + '")');
      root.setAttribute('data-bg', 'image');
    } else {
      root.style.removeProperty('--bg-image');
      root.setAttribute('data-bg', 'none');
    }
    return look;
  }

  paintLook(readLook());

  window.__ghoulLook = {
    KEY: LOOK_KEY,
    DEFAULTS: LOOK_DEFAULTS,
    read: readLook,
    paint: paintLook,
    image: safeImageUrl
  };

  window.__ghoulTheme = {
    DEFAULT: DEFAULT_ACCENT,
    current: function () {
      try { return localStorage.getItem(ACCENT_KEY) || DEFAULT_ACCENT; } catch (e) { return DEFAULT_ACCENT; }
    },
    apply: function (hex) {
      paintAccent(hex);
      var meta = document.querySelector('meta[name="theme-color"]');
      if (meta) meta.setAttribute('content', getComputedStyle(root).getPropertyValue('--bg').trim() || '#070509');
      try {
        if (parseHex(hex) && hex.toLowerCase() !== DEFAULT_ACCENT) localStorage.setItem(ACCENT_KEY, hex);
        else localStorage.removeItem(ACCENT_KEY);
      } catch (e) {}
    }
  };

  /* ---------------- tab titles + icons (panic screens and cloak) ---------------- */

  var PANIC_KEY = 'ghoul:panic';
  var CLOAK_KEY = 'ghoul:cloak';
  var CLOAK_ON_KEY = 'ghoul:cloakOn';

  function readKey(key, fallback) {
    try { return localStorage.getItem(key) || fallback; } catch (e) { return fallback; }
  }

  function writeKey(key, value) {
    try { localStorage.setItem(key, value); } catch (e) {}
  }

  /* Before this rename the panic choice lived under the cloak key. */
  try {
    if (!localStorage.getItem(PANIC_KEY) && localStorage.getItem(CLOAK_KEY)) {
      localStorage.setItem(PANIC_KEY, localStorage.getItem(CLOAK_KEY));
    }
  } catch (e) {}
  var KINDS = {
    schoology: {
      title: 'Schoology',
      icon: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64"><rect width="64" height="64" rx="12" fill="#133F69"/><text x="32" y="45" font-family="Arial,Helvetica,sans-serif" font-size="38" font-weight="700" fill="#ffffff" text-anchor="middle">S</text></svg>'
    },
    classroom: {
      title: 'Classroom',
      url: 'https://ssl.gstatic.com/classroom/favicon.png',
      icon: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64"><rect width="64" height="64" rx="12" fill="#188038"/><rect x="12" y="16" width="40" height="28" rx="3" fill="#ffffff"/><rect x="17" y="22" width="14" height="3" rx="1.5" fill="#188038"/><rect x="17" y="29" width="30" height="3" rx="1.5" fill="#188038"/><rect x="17" y="36" width="22" height="3" rx="1.5" fill="#188038"/><circle cx="46" cy="45" r="9" fill="#fbbc04"/><circle cx="46" cy="43" r="3.2" fill="#188038"/><path d="M40 51c0-3.2 2.7-5 6-5s6 1.8 6 5z" fill="#188038"/></svg>'
    },
    drive: {
      title: 'My Drive - Google Drive',
      url: 'https://ssl.gstatic.com/docs/doclist/images/drive_favicon_2026_32dp.png',
      icon: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64"><rect width="64" height="64" rx="12" fill="#ffffff"/><path d="M32 10 44.5 31.4 32 38.3 19.5 31.4Z" fill="#FBBC04"/><path d="M44.5 31.4 57 52H32v-13.7Z" fill="#4285F4"/><path d="M19.5 31.4 32 38.3V52H7Z" fill="#0F9D58"/></svg>'
    },
    search: {
      title: 'Google',
      url: 'https://www.gstatic.com/images/branding/searchlogo/ico/favicon.ico',
      icon: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64"><rect width="64" height="64" rx="12" fill="#ffffff"/><text x="32" y="47" font-family="Arial,Helvetica,sans-serif" font-size="42" font-weight="700" fill="#4285F4" text-anchor="middle">G</text></svg>'
    }
  };

  function iconUrl(svg) {
    return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  }

  function iconLinks() {
    return Array.prototype.slice.call(
      document.querySelectorAll('link[rel~="icon"], link[rel="apple-touch-icon"]')
    );
  }

  /* Each icon link keeps its original href/type/sizes so it can be restored. */
  var iconSlots = iconLinks().map(function (el) {
    return {
      el: el,
      href: el.getAttribute('href'),
      type: el.getAttribute('type'),
      sizes: el.getAttribute('sizes'),
      svg: el.getAttribute('type') === 'image/svg+xml',
      touch: el.rel === 'apple-touch-icon'
    };
  });
  var pageTitle = document.title;
  var iconToken = 0;

  function restorePageIcons() {
    iconToken++;
    iconSlots.forEach(function (slot) {
      if (slot.href) slot.el.setAttribute('href', slot.href); else slot.el.removeAttribute('href');
      if (slot.type) slot.el.setAttribute('type', slot.type); else slot.el.removeAttribute('type');
      if (slot.sizes) slot.el.setAttribute('sizes', slot.sizes); else slot.el.removeAttribute('sizes');
    });
  }

  /* Drawn stand-in icon: inline SVG plus PNG twins for Safari and pinned tabs. */
  function paintDrawnIcon(svg, token) {
    var svgUrl = iconUrl(svg);
    iconSlots.forEach(function (slot) {
      if (!slot.svg) return;
      slot.el.setAttribute('href', svgUrl);
      slot.el.setAttribute('type', 'image/svg+xml');
    });
    var img = new Image();
    img.onload = function () {
      if (token !== iconToken) return;
      var canvas = document.createElement('canvas');
      var ctx = canvas.getContext('2d');
      if (!ctx) return;
      iconSlots.forEach(function (slot) {
        if (slot.svg) return;
        var size = slot.touch ? 180 : 32;
        canvas.width = size;
        canvas.height = size;
        ctx.clearRect(0, 0, size, size);
        ctx.drawImage(img, 0, 0, size, size);
        try {
          slot.el.setAttribute('href', canvas.toDataURL('image/png'));
          slot.el.setAttribute('type', 'image/png');
          slot.el.setAttribute('sizes', size + 'x' + size);
        } catch (e) {}
      });
    };
    img.src = svgUrl;
  }

  /* Real app favicon: use the published file, fall back to the drawing if it fails. */
  function paintRemoteIcon(url, fallbackSvg, token) {
    var probe = new Image();
    probe.onload = function () {
      if (token !== iconToken) return;
      iconSlots.forEach(function (slot) {
        slot.el.setAttribute('href', url);
        slot.el.removeAttribute('type');
        slot.el.removeAttribute('sizes');
      });
    };
    probe.onerror = function () {
      if (token !== iconToken) return;
      paintDrawnIcon(fallbackSvg, token);
    };
    probe.src = url;
  }

  function paintIcons(spec) {
    var token = ++iconToken;
    if (spec.url) paintRemoteIcon(spec.url, spec.icon, token);
    else paintDrawnIcon(spec.icon, token);
  }

  var panicDesign = readKey(PANIC_KEY, 'schoology');
  var cloakDesign = readKey(CLOAK_KEY, 'schoology');
  var cloakOn = readKey(CLOAK_ON_KEY, '0') === '1';

  /* The page tabs leave a one-shot stamp in sessionStorage. Switching library
     is not a fresh visit, so the decoy must not replay; a cold load or a
     refresh has no stamp and still shows it. The age check drops stale stamps
     (a click that never navigated, a tab restored hours later). */
  var skipPanic = false;
  try {
    var jumpAt = Number(sessionStorage.getItem('ghoul:pageJump'));
    sessionStorage.removeItem('ghoul:pageJump');
    skipPanic = isFinite(jumpAt) && jumpAt > 0 && Date.now() - jumpAt < 15000;
  } catch (e) {}

  function applyTab(kind) {
    var spec = KINDS[kind];
    if (!spec) return false;
    document.title = spec.title;
    paintIcons(spec);
    return true;
  }

  function originalTab() {
    document.title = pageTitle;
    restorePageIcons();
  }

  /* Whatever the tab should show when no panic screen is up. */
  function settleTab() {
    if (cloakOn) applyTab(cloakDesign);
    else originalTab();
  }

  window.__panicTab = {
    kinds: KINDS,
    skipped: skipPanic,
    apply: applyTab,
    restore: settleTab,
    get: function () { return panicDesign; },
    set: function (kind) { panicDesign = kind; writeKey(PANIC_KEY, kind); },
    /* app.js names the page once the catalogue is known, so cloak-off and
       panic-off put back the right title. Keeps a live decoy untouched;
       "none" means no decoy is up (panic off, or a skipped page switch). */
    setPageTitle: function (title) {
      pageTitle = title;
      var decoy = root.getAttribute('data-panic');
      if (decoy && decoy !== 'none') return;
      if (cloakOn) applyTab(cloakDesign);
      else document.title = title;
    }
  };

  window.__ghoulCloak = {
    design: function () { return cloakDesign; },
    on: function () { return cloakOn; },
    setDesign: function (kind) {
      cloakDesign = kind;
      writeKey(CLOAK_KEY, kind);
      if (cloakOn) applyTab(kind);
    },
    setOn: function (value) {
      cloakOn = !!value;
      writeKey(CLOAK_ON_KEY, cloakOn ? '1' : '0');
      if (cloakOn) applyTab(cloakDesign);
      else originalTab();
    }
  };

  /* "none" hides the overlay before paint, so a skipped decoy never flashes. */
  root.setAttribute('data-panic', skipPanic ? 'none' : panicDesign);
  if (skipPanic) settleTab();
  else if (panicDesign !== 'none') applyTab(panicDesign);
  else if (cloakOn) applyTab(cloakDesign);
})();

