inter","f":"fucker.html","i":500,"g":["arcade"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/176.jpg","d":"Track running simulation"},{"n":"Five Nights at Epstein","f":"2019.html","i":2019,"g":["horror"],"d":"A secret escape game where you navigate through mysterious locations"},{"n":"Twitch Tetris","u":"https://godlover89.github.io/Twitch-Tetris/","i":3544,"g":["puzzle"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/89.jpg","d":"Classic block stacking puzzle"},{"n":"Impossible Quiz 2","u":"https://xoriushourz.github.io/ImpossibleQuiz2/","i":3548,"g":["arcade"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/63.jpg","d":"Tricky brain-teasing questions"},{"n":"Sort The Court","u":"https://noahsamazingtutoringhelp.github.io/skdpiwjamoksld/","i":4940,"g":["puzzle"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/181.jpg","d":"Kingdom management game"},{"n":"Kart Bros","u":"https://kartbros.io/?ms=1&msstart_sdk_init=eyJwYXJlbnRPcmlnaW4iOiJodHRwczovL3d3dy5tc24uY29tIiwiY2xpZW50SWQiOiIyRDNDRjBEODBGRUQ2RDVDMDFDN0U2MjEwRTlFNkNGRCIsImxvY2FsZSI6ImVuLXVzIiwiZW50cnlQb2ludElkIjoiIiwic3dpdGNoR2FtZVBheWxvYWQiOnsic3dpdGNoZWRUbyI6IjlwOTc4OHM2OTdqYyIsInZhbHVlIjp7fX19#","i":5375,"g":["racing","multiplayer"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/260.jpg","d":"Free online kart racing game with wild antics, power-ups, and multiplayer action"},{"n":"Thorns and Balloons","u":"https://noahsamazingtutoringhelp.github.io/ScienceStudyBuddy/","i":5912,"g":["arcade"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/144.jpg","d":"Balloon popping game"},{"n":"Football Bros","u":"https://fb.crispyclean.org/","i":6022,"g":["sports","classic"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/194.jpg","d":"Arcade football with simple controls and power-ups"},{"n":"Toca-Boca-World","u":"https://ud-gles3games.shared-osj.k8s.n2i.io/?deeplinksURI=null%3A%2F%2F&deeplinksApp=com.tocaboca.tocalifeworld&quotaBytes=89000000&naturalOrientation=portrait&invertNaturalOrientation&forcedNaturalOrientation&jitterBufferMin=0&deeplinksService=true&backOnDisconnected=true&disconnectedMessage=null&api=%7B%22back%22%3Afalse%7D&title=Toca+Boca+World","i":6126,"g":["arcade"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/206.jpg","d":"A digital toy box where you create your own stories and worlds."},{"n":"Speed Stars","u":"https://rawcdn.githack.com/BeezBumba/SpeedStarsv2/67d3a926357cf35e2a2efc5ac5fc29c786c8cbda/index.html","i":7231,"g":["racing"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/317.jpg","d":"Test your reflexes in this competitive athletic racing game"},{"n":"Doom 3","u":"https://doom3kaidensarcade.netlify.app/","i":7284,"g":["horror","action"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/282.jpg","d":"A sci-fi horror first-person shooter at a Mars research base where teleportation experiments open a gateway to Hell, unleashing demons and zombies."},{"n":"Among Us","u":"https://ud-gles3games.shared-osj.k8s.n2i.io/?deeplinksURI=null%3A%2F%2F&deeplinksApp=com.innersloth.spacemafia&naturalOrientation=landscape&forcedNaturalOrientation&autofitOnConnect&jitterBufferMin=0&deeplinksService=true&backOnDisconnected=true&disconnectedMessage=null&api=%7B%22back%22%3Afalse%7D&title=Among+Us","i":7419,"g":["multiplayer"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/17.jpg","x":1,"d":"Social deduction identifying impostors"},{"n":"Super Monkey Ball","u":"https://rawcdn.githack.com/slqntdevss/quasar/main/public/assets/storage/html/smb/index.html","i":8469,"g":["arcade"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/336.jpg","d":"Roll your ball through challenging suspended courses, reach the goal and collect bannanas"},{"n":"Club Penguin","u":"https://play.cplegacy.com/","i":8589,"g":["arcade"],"c":"https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/images/140.jpg","d":"Virtual world social game"}];

/* ============================================================
   GHOULISH
   Two game pages, both mirrored from public GitHub catalogues:
     GnMath          -> gnmath (html-main/), covers from gn-math.dev
     Noah's Tutoring -> Noahs-Calculus-Tutor (games/, images/)
   Game files are html pages: we fetch one as text, inject a <base> so its
   assets resolve, then write it into a same-origin iframe so saves still
   work. Ports that live on someone else's site are framed directly.
   ============================================================ */
(() => {
  'use strict';

  const PANIC_MS = 5000;
  let panicApi = null;
  let syncCloakToggle = null;
  let closeMenuHook = null;
  initPanic();

  const PAGE_SIZE = 72;

  // Each library is a page: ?page=gnmath (the default) and ?page=noahs.
  const LIBRARIES = {
    gnmath: {
      id: 'gnmath',
      label: 'GnMath',
      catalogue: 'GHOUL_GAMES',
      bases: [
        'https://cdn.jsdelivr.net/gh/SFDGSDFGSDFGSDFGSDFG/gnmath@main/html-main/',
        'https://raw.githubusercontent.com/SFDGSDFGSDFGSDFGSDFG/gnmath/main/html-main/'
      ],
      coverBase: 'https://gn-math.dev/s/EE0_FEFXflkxUx5iECccXCcNRB9_GDdDXysSex5LLgFQGDgFPFIDP1U3F08uFkEtPBc7WV8/',
      spotlight: [
        'Skate 3', 'ULTRAKILL', 'R.E.P.O', 'Buckshot Roulette', 'Geometry Dash', 'Hollow Knight',
        'Minecraft 1.12.2', 'Cuphead', "That's Not My Neighbor", 'Bendy and the Ink Machine',
        'Pizza Tower'
      ],
      title: () => 'Ghoulish — 800+ free browser games after dark',
      description: () => 'Ghoulish is a red-and-black arcade crypt with 800+ free browser games — horror, action, multiplayer, retro and more. No downloads, no sign-up, just play.',
      eyebrow: '>_<',
      lede: 'Over eight hundred browser games!',
      browseEyebrow: 'games',
      vault: 'the library',
      browseLink: 'Browse',
      repo: ['https://github.com/SFDGSDFGSDFGSDFGSDFG/gnmath', 'GnMath catalogue on GitHub']
    },
    noahs: {
      id: 'noahs',
      label: "Noah's Tutoring",
      catalogue: 'NOAHS_GAMES',
      bases: [
        'https://cdn.jsdelivr.net/gh/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor@master/games/',
        'https://raw.githubusercontent.com/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor/master/games/'
      ],
      coverBase: '',
      spotlight: [
        'Deltarune', 'Undertale', 'Stardew Valley', 'Pizza Tower', 'Geometry Dash',
        'Plants Vs Zombies', 'Granny 3', 'Wordle', 'Monkey Mart'
      ],
      title: (count) => `Noah's Tutoring — ${count} free browser games · Ghoulish`,
      description: (count) => `${count} browser games from the Noah's Tutoring hub, mirrored into Ghoulish: horror, action, retro, sandbox and more. No downloads, no sign-up.`,
      eyebrow: "Noah's Tutoring · the tutoring vault",
      lede: "A second vault, borrowed from the Noah's Tutoring hub — hundreds more games, wired into the same crypt gate. No downloads, no accounts, no mercy.",
      browseEyebrow: "Noah's Tutoring",
      vault: 'the tutoring vault',
      browseLink: 'Browse the vault',
      repo: ['https://github.com/NoahsAmazingTutoringHelp/Noahs-Calculus-Tutor', "Noah's Tutoring catalogue on GitHub"]
    }
  };

  const PAGE_IDS = Object.keys(LIBRARIES);
  const urlParams = new URLSearchParams(window.location.search);
  const requestedPage = (urlParams.get('page') || '').toLowerCase();
  const PAGE_ID = LIBRARIES[requestedPage] ? requestedPage : PAGE_IDS[0];
  const LIB = LIBRARIES[PAGE_ID];
  const isDefaultPage = PAGE_ID === PAGE_IDS[0];
  // GnMath keeps the plain ?game= URLs it has always had.
  const pageQuery = isDefaultPage ? '' : `page=${PAGE_ID}&`;

  const GAMES = Array.isArray(window[LIB.catalogue]) ? window[LIB.catalogue] : [];
  const GAME_BASES = LIB.bases;
  const FAV_KEY = isDefaultPage ? 'ghoul:favourites' : `ghoul:favourites:${PAGE_ID}`;
  const RECENT_KEY = isDefaultPage ? 'ghoul:recent' : `ghoul:recent:${PAGE_ID}`;

  const ICON_PLAY = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 5.5v13l11-6.5-11-6.5Z"/></svg>';
  const ICON_HEART = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 20s-7.5-4.6-7.5-9.4A4.1 4.1 0 0 1 12 7.6a4.1 4.1 0 0 1 7.5 3c0 4.8-7.5 9.4-7.5 9.4Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>';
  const ICON_SKULL = '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="M24 3.5c-9.9 0-17.8 7.4-17.8 16.4 0 5.4 2.7 10.1 6.9 13v5.6c0 2.3 1.9 4.2 4.2 4.2h1.6v-4.1h2.2v4.1h2.2v-4.1h2.2v4.1h2.2v-4.1h2.2v4.1h1.6c2.3 0 4.2-1.9 4.2-4.2v-5.6c4.2-2.9 6.9-7.6 6.9-13C41.8 10.9 33.9 3.5 24 3.5Z" fill="currentColor"/><ellipse cx="17.2" cy="20.4" rx="4.5" ry="4.9" fill="#0a0609"/><ellipse cx="30.8" cy="20.4" rx="4.5" ry="4.9" fill="#0a0609"/><path d="M24 26.2l-2.7 4.6h5.4L24 26.2Z" fill="#0a0609"/></svg>';

  const GENRE_LABELS = {
    horror: 'Horror', action: 'Action', adventure: 'Adventure', rhythm: 'Rhythm',
    racing: 'Racing', sports: 'Sports', puzzle: 'Puzzle', multiplayer: 'Multiplayer',
    sandbox: 'Sandbox', emulator: 'Emulator', classic: 'Retro', arcade: 'Arcade',
    tools: 'Tool', port: 'Port'
  };

  const FILTERS = [
    { id: 'all', label: 'All games' },
    { id: 'featured', label: 'Featured' },
    { id: 'horror', label: 'Horror' },
    { id: 'action', label: 'Action' },
    { id: 'multiplayer', label: 'Multiplayer' },
    { id: 'sandbox', label: 'Sandbox' },
    { id: 'puzzle', label: 'Puzzle' },
    { id: 'racing', label: 'Racing' },
    { id: 'sports', label: 'Sports' },
    { id: 'rhythm', label: 'Rhythm' },
    { id: 'adventure', label: 'Adventure' },
    { id: 'classic', label: 'Retro' },
    { id: 'arcade', label: 'Arcade' },
    { id: 'emulator', label: 'Emulators' },
    { id: 'tools', label: 'Tools' },
    { id: 'favourites', label: 'Favourites' }
  ];

  const LOADER_TIPS = [
    'Tip: press <kbd>Esc</kbd> to crawl back out.',
    'Tip: press <kbd>/</kbd> to search the whole crypt.',
    'Tip: press <kbd>R</kbd> for a random game.',
    'Tip: hit the heart to keep a game in your favourites.',
    'Tip: the ⛶ button puts the game fullscreen.'
  ];

  const $ = (sel, root = document) => root.querySelector(sel);
  const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
  const esc = (str) => String(str).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  const gameById = new Map(GAMES.map((g) => [g.i, g]));
  const coverUrl = (g) => g.c || (LIB.coverBase ? `${LIB.coverBase}${g.i}.png` : '');
  const genreLabel = (g) => (g.g && g.g[0] ? (GENRE_LABELS[g.g[0]] || g.g[0]) : 'Arcade');
  const gameHref = (g) => `?${pageQuery}game=${g.i}`;
  const isExternal = (g) => Boolean(g && typeof g.u === 'string' && /^https?:\/\//i.test(g.u));

  /* ---------------- storage ---------------- */

  const storage = {
    read(key, fallback) {
      try {
        const raw = localStorage.getItem(key);
        const parsed = raw ? JSON.parse(raw) : fallback;
        return parsed == null ? fallback : parsed;
      } catch (_) { return fallback; }
    },
    write(key, value) {
      try { localStorage.setItem(key, JSON.stringify(value)); } catch (_) { /* private mode */ }
    }
  };

  /* ---------------- look & feel ---------------- */

  const LOOK_KEY = 'ghoul:look';
  const LOOK_DEFAULTS = {
    font: 'cinzel', corners: 'round', density: 'cozy', ambience: 'full', motion: 'on',
    bg: '', name: '', tagline: '', spotlight: true, recent: true, how: true
  };
  const LOOK_ALLOWED = {
    font: ['cinzel', 'grotesk', 'serif', 'mono'],
    corners: ['round', 'sharp'],
    density: ['compact', 'cozy', 'large'],
    ambience: ['full', 'calm', 'off'],
    motion: ['on', 'off']
  };

  function safeImageUrl(value) {
    const url = String(value || '').trim().slice(0, 500);
    if (!url) return '';
    if (/^(https?:|data:image\/)/i.test(url)) {
      try { new URL(url); return url; } catch (_) { return ''; }
    }
    return /^[./\w%:@~?&()=-]+$/.test(url) ? url : '';
  }

  function cssUrl(url) {
    return url.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\r\n]/g, '');
  }

  function readLook() {
    let raw = null;
    try { raw = JSON.parse(localStorage.getItem(LOOK_KEY) || 'null'); } catch (_) {}
    const look = { ...LOOK_DEFAULTS };
    if (!raw || typeof raw !== 'object') return look;
    Object.keys(LOOK_ALLOWED).forEach((key) => {
      if (LOOK_ALLOWED[key].includes(raw[key])) look[key] = raw[key];
    });
    look.spotlight = raw.spotlight !== false;
    look.recent = raw.recent !== false;
    look.how = raw.how !== false;
    look.name = typeof raw.name === 'string' ? raw.name.slice(0, 18) : '';
    look.tagline = typeof raw.tagline === 'string' ? raw.tagline.slice(0, 70) : '';
    look.bg = safeImageUrl(raw.bg);
    return look;
  }

  function applyLook() {
    const root = document.documentElement;
    Object.keys(LOOK_ALLOWED).forEach((key) => root.setAttribute(`data-${key}`, state.look[key]));
    root.setAttribute('data-home-spotlight', state.look.spotlight === false ? 'off' : 'on');
    root.setAttribute('data-home-recent', state.look.recent === false ? 'off' : 'on');
    root.setAttribute('data-home-how', state.look.how === false ? 'off' : 'on');
    if (state.look.bg) {
      root.style.setProperty('--bg-image', `url("${cssUrl(state.look.bg)}")`);
      root.setAttribute('data-bg', 'image');
    } else {
      root.style.removeProperty('--bg-image');
      root.setAttribute('data-bg', 'none');
    }
    // A paused spotlight should not keep rotating behind the scenes.
    if (typeof restartSpotTimer === 'function') restartSpotTimer();
  }

  function siteName() {
    return (state.look.name || '').trim() || 'Ghoulish';
  }

  function applyBranding() {
    const name = siteName();
    $$('.brand__name').forEach((node) => { node.textContent = name === 'Ghoulish' ? 'GHOULISH' : name; });
    $$('.brand').forEach((node) => node.setAttribute('aria-label', `${name} home`));
    const hero = $('.hero__title');
    if (hero) hero.textContent = name;
    const footerName = $('#footerName');
    if (footerName) footerName.textContent = name;
    const lede = $('#heroLede');
    if (lede) lede.textContent = (state.look.tagline || '').trim() || LIB.lede;
    if (state.baseTitle) {
      const title = state.baseTitle.replace(/Ghoulish/g, name);
      if (window.__panicTab && window.__panicTab.setPageTitle) window.__panicTab.setPageTitle(title);
      else document.title = title;
    }
  }

  function writeLook() {
    storage.write(LOOK_KEY, state.look);
  }

  const state = {
    filter: 'all',
    sort: 'featured',
    search: '',
    shown: PAGE_SIZE,
    list: [],
    favourites: new Set(storage.read(FAV_KEY, [])),
    recent: storage.read(RECENT_KEY, []).filter((id) => gameById.has(id)),
    current: null,
    loadToken: 0,
    spotIndex: 0,
    baseTitle: '',
    look: readLook()
  };

  /* ---------------- elements ---------------- */

  const els = {
    grid: $('#grid'),
    empty: $('#empty'),
    moreWrap: $('#moreWrap'),
    loadMore: $('#loadMore'),
    sentinel: $('#sentinel'),
    filters: $('#filters'),
    search: $('#search'),
    sort: $('#sort'),
    resultCount: $('#resultCount'),
    recentSection: $('#recentSection'),
    recentRail: $('#recentRail'),
    player: $('#player'),
    stage: $('#stage'),
    loader: $('#loader'),
    loaderTip: $('#loaderTip'),
    playerError: $('#playerError'),
    playerErrorText: $('#playerErrorText'),
    playerTitle: $('#playerTitle'),
    playerAuthor: $('#playerAuthor'),
    playerThumb: $('#playerThumb'),
    playerFav: $('#playerFav'),
    toast: $('#toast'),
    spotBg: $('#spotBg'),
    spotCover: $('#spotCover'),
    spotTitle: $('#spotTitle'),
    spotMeta: $('#spotMeta'),
    spotDots: $('#spotDots'),
    spotFav: $('#spotFav'),
    heroPlay: $('#heroPlay'),
    heroGameName: $('#heroGameName')
  };

  /* ---------------- cards ---------------- */

  function isFav(id) { return state.favourites.has(id); }

  function cardHTML(g) {
    const fav = isFav(g.i);
    const initial = esc((g.n || '?').trim().charAt(0).toUpperCase());
    const cover = coverUrl(g);
    return `<article class="card" data-id="${g.i}">
      <a class="card__link" href="${gameHref(g)}" aria-label="Play ${esc(g.n)}"></a>
      <div class="card__media" data-initial="${initial}">
        ${cover ? `<img class="card__img" src="${esc(cover)}" alt="" loading="lazy" decoding="async">` : ''}
        <span class="card__fallback" aria-hidden="true">${ICON_SKULL}<em>${initial}</em></span>
        <span class="card__play" aria-hidden="true">${ICON_PLAY}</span>
        ${g.x ? '<span class="card__star" aria-hidden="true">★</span>' : ''}
        <button class="card__fav${fav ? ' is-on' : ''}" data-fav="${g.i}" type="button" aria-pressed="${fav}" aria-label="Favourite ${esc(g.n)}">${ICON_HEART}</button>
      </div>
      <div class="card__info">
        <h3 class="card__name">${esc(g.n)}</h3>
        <p class="card__genre">${esc(genreLabel(g))}</p>
      </div>
    </article>`;
  }

  function bindImages(root) {
    $$('.card__img', root).forEach((img) => {
      if (img.dataset.bound) return;
      img.dataset.bound = '1';
      const card = img.closest('.card');
      const fail = () => { if (card) card.classList.add('no-cover'); };
      img.addEventListener('load', () => {
        img.classList.add('is-loaded');
        if (card) card.classList.remove('no-cover');
      }, { once: true });
      img.addEventListener('error', fail, { once: true });
      if (img.complete && img.naturalWidth > 0) img.classList.add('is-loaded');
    });
  }

  /* ---------------- filtering ---------------- */

  function matchesFilter(g) {
    if (state.filter === 'all') return true;
    if (state.filter === 'featured') return Boolean(g.x);
    if (state.filter === 'favourites') return isFav(g.i);
    return Array.isArray(g.g) && g.g.includes(state.filter);
  }

  // Common shorthand people actually type: "fnaf" should find Five Nights.
  const ALIASES = {
    fnaf: 'five nights', fnf: 'friday night funkin', gd: 'geometry dash',
    mc: 'minecraft', gta: 'grand theft', cod: 'call of duty',
    '1v1': '1v1.lol'
  };

  function matchesSearch(g) {
    if (!state.search) return true;
    const haystack = `${g.n} ${g.a || ''} ${g.d || ''} ${(g.g || []).join(' ')}`.toLowerCase();
    return state.search.toLowerCase().split(/\s+/).filter(Boolean).every((term) =>
      haystack.includes(term) || (ALIASES[term] ? haystack.includes(ALIASES[term]) : false)
    );
  }

  function buildList() {
    const list = GAMES.filter((g) => matchesFilter(g) && matchesSearch(g));
    const sort = state.sort;
    const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
    list.sort((a, b) => {
      if (sort === 'az') return collator.compare(a.n, b.n);
      if (sort === 'za') return collator.compare(b.n, a.n);
      if (sort === 'new') return b.i - a.i;
      if (Boolean(b.x) !== Boolean(a.x)) return b.x ? 1 : -1;
      return a.i - b.i;
    });
    state.list = list;
  }

  function renderFilters() {
    const counts = { all: GAMES.length, featured: GAMES.filter((g) => g.x).length, favourites: state.favourites.size };
    els.filters.innerHTML = FILTERS.map((f) => {
      const count = counts[f.id] != null ? counts[f.id] : GAMES.filter((g) => (g.g || []).includes(f.id)).length;
      return { f, count };
    }).filter(({ f, count }) =>
      // Only show genres this page actually has, so every chip is truthful.
      count > 0 || f.id === 'all' || f.id === 'favourites' || f.id === state.filter
    ).map(({ f, count }) =>
      `<button class="chip${state.filter === f.id ? ' is-active' : ''}" type="button" data-filter="${f.id}" aria-pressed="${state.filter === f.id}">
        ${esc(f.label)}<span>${count}</span>
      </button>`
    ).join('');
  }

  function renderGrid(reset = true) {
    if (reset) {
      state.shown = PAGE_SIZE;
      els.grid.innerHTML = '';
    }
    const slice = state.list.slice(state.shown - PAGE_SIZE, state.shown);
    const frag = document.createElement('div');
    frag.innerHTML = slice.map(cardHTML).join('');
    const nodes = Array.from(frag.children);
    nodes.forEach((node, index) => {
      node.style.animationDelay = `${Math.min(index * 8, 240)}ms`;
      els.grid.appendChild(node);
    });
    bindImages(els.grid);

    const total = state.list.length;
    const showing = Math.min(state.shown, total);
    els.empty.hidden = total !== 0;
    els.grid.hidden = total === 0;
    els.moreWrap.hidden = showing >= total;
    els.loadMore.textContent = `Load ${Math.min(PAGE_SIZE, total - showing)} more games`;

    if (state.search) {
      els.resultCount.textContent = `${total} ${total === 1 ? 'game' : 'games'} for “${state.search}”`;
    } else {
      const active = FILTERS.find((f) => f.id === state.filter);
      els.resultCount.textContent = state.filter === 'all'
        ? `${total} games in ${LIB.vault}`
        : `${total} ${total === 1 ? 'game' : 'games'} · ${active ? active.label : state.filter}`;
    }
  }

  function refresh() {
    buildList();
    renderFilters();
    renderGrid(true);
  }

  function setFilter(id, { scroll = false } = {}) {
    state.filter = id;
    state.search = '';
    els.search.value = '';
    refresh();
    if (scroll) $('#browse').scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  /* ---------------- recently played ---------------- */

  function renderRecent() {
    const list = state.recent.map((id) => gameById.get(id)).filter(Boolean).slice(0, 12);
    els.recentSection.hidden = list.length === 0;
    if (!list.length) { els.recentRail.innerHTML = ''; return; }
    els.recentRail.innerHTML = list.map(cardHTML).join('');
    bindImages(els.recentRail);
  }

  function pushRecent(id) {
    state.recent = [id, ...state.recent.filter((x) => x !== id)].slice(0, 12);
    storage.write(RECENT_KEY, state.recent);
    renderRecent();
  }

  /* ---------------- favourites ---------------- */

  function syncFav(id) {
    const on = isFav(id);
    $$(`[data-fav="${id}"]`).forEach((btn) => {
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-pressed', String(on));
    });
    if (state.current && state.current.i === id) {
      els.playerFav.classList.toggle('is-on', on);
      els.playerFav.setAttribute('aria-pressed', String(on));
    }
    const spotlight = currentSpotlight();
    if (spotlight && spotlight.i === id) {
      els.spotFav.classList.toggle('is-on', on);
      els.spotFav.setAttribute('aria-pressed', String(on));
    }
  }

  function toggleFav(id) {
    if (!id && id !== 0) return;
    if (state.favourites.has(id)) state.favourites.delete(id);
    else state.favourites.add(id);
    storage.write(FAV_KEY, [...state.favourites]);
    syncFav(id);
    const chip = $('[data-filter="favourites"]');
    if (chip) chip.querySelector('span').textContent = state.favourites.size;
    if (state.filter === 'favourites') refresh();
    toast(isFav(id) ? 'Kept in your favourites' : 'Removed from favourites');
  }

  /* ---------------- spotlight ---------------- */

  let spotTimer = null;

  function spotlightGames() {
    const picks = LIB.spotlight.map((name) => GAMES.find((g) => g.n === name)).filter(Boolean);
    return picks.length ? picks : GAMES.filter((g) => g.x).slice(0, 8);
  }

  function currentSpotlight() {
    const pool = spotlightGames();
    return pool.length ? pool[state.spotIndex % pool.length] : null;
  }

  function renderSpotlight(index = state.spotIndex) {
    const pool = spotlightGames();
    if (!pool.length) return;
    state.spotIndex = ((index % pool.length) + pool.length) % pool.length;
    const game = pool[state.spotIndex];
    els.spotBg.src = coverUrl(game);
    els.spotCover.src = coverUrl(game);
    els.spotCover.alt = `${game.n} cover art`;
    els.spotTitle.textContent = game.n;
    els.spotMeta.textContent = `${genreLabel(game)}${game.a ? ' · ' + game.a : ''}`;
    els.heroGameName.textContent = game.n;
    els.spotFav.classList.toggle('is-on', isFav(game.i));
    els.spotFav.setAttribute('aria-pressed', String(isFav(game.i)));
    els.spotDots.innerHTML = pool.map((g, i) =>
      `<button type="button" data-spot="${i}" class="${i === state.spotIndex ? 'is-active' : ''}" aria-label="Show ${esc(g.n)}" aria-selected="${i === state.spotIndex}"></button>`
    ).join('');
    restartSpotTimer();
  }

  function restartSpotTimer() {
    clearInterval(spotTimer);
    spotTimer = null;
    if (state.look.motion === 'off') return;
    spotTimer = setInterval(() => renderSpotlight(state.spotIndex + 1), 7000);
  }

  /* ---------------- player ---------------- */

  function showLoader() {
    els.loaderTip.innerHTML = LOADER_TIPS[Math.floor(Math.random() * LOADER_TIPS.length)];
    els.loader.classList.remove('is-hidden');
    els.playerError.hidden = true;
  }

  function hideLoader() {
    els.loader.classList.add('is-hidden');
  }

  function showError(message) {
    hideLoader();
    els.playerErrorText.textContent = message || "That game didn't load. The CDN might be having a bad night.";
    els.playerError.hidden = false;
  }

  async function fetchGame(game) {
    // Some ports are hosted by their own authors and refuse to be copied;
    // those get framed from their own origin instead of fetched.
    if (isExternal(game)) return { external: game.u };
    let lastError = null;
    for (const base of GAME_BASES) {
      const url = base + game.f;
      try {
        const res = await fetch(url, { cache: 'force-cache' });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const html = await res.text();
        if (html.length < 40) throw new Error('Empty game file');
        return { html, url };
      } catch (error) {
        lastError = error;
      }
    }
    throw lastError || new Error('Game unavailable');
  }

  function baseFor(html, url) {
    const folder = url.slice(0, url.lastIndexOf('/') + 1);
    const match = html.match(/<base\b[^>]*\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s">]+))/i);
    const declared = match ? (match[1] ?? match[2] ?? match[3]) : '';
    if (!declared) return folder;
    try { return new URL(declared, folder).href; } catch (_) { return folder; }
  }

  function withBase(html, url) {
    const tag = `<base href="${baseFor(html, url)}">`;
    if (/<base\b[^>]*>/i.test(html)) return html.replace(/<base\b[^>]*>/i, tag);
    if (/<head[^>]*>/i.test(html)) return html.replace(/<head[^>]*>/i, (m) => m + tag);
    if (/<html[^>]*>/i.test(html)) return html.replace(/<html[^>]*>/i, (m) => m + tag);
    return tag + html;
  }

  function mountFrame(title) {
    const old = $('#gameFrame');
    if (old) old.remove();
    const frame = document.createElement('iframe');
    frame.id = 'gameFrame';
    frame.className = 'frame';
    frame.title = title || 'Game';
    frame.setAttribute('allow', 'fullscreen; autoplay; gamepad; clipboard-write; accelerometer; gyroscope; magnetometer');
    els.stage.appendChild(frame);
    return frame;
  }

  async function runGame(game) {
    const token = ++state.loadToken;
    showLoader();
    const frame = mountFrame(game.n);
    if (isExternal(game)) {
      // Cross-origin port: no text to rewrite, so point the frame at it and
      // lift the gate on load (or after a grace period if it stays silent).
      frame.referrerPolicy = 'no-referrer';
      frame.src = game.u;
      const settle = () => { if (token === state.loadToken) hideLoader(); };
      frame.addEventListener('load', settle, { once: true });
      setTimeout(settle, 8000);
      return;
    }
    try {
      const { html, url } = await fetchGame(game);
      if (token !== state.loadToken) return;
      const doc = frame.contentDocument;
      if (!doc) throw new Error('The browser blocked the game frame.');
      doc.open();
      doc.write(withBase(html, url));
      doc.close();
      // Game frames are same-origin, so let Esc escape the crypt even
      // when keyboard focus is inside the game.
      doc.addEventListener('keydown', (event) => {
        if (event.key === 'Escape' && !document.fullscreenElement) closePlayer();
        // Panic still works while a game has keyboard focus.
        if (event.code === 'Backquote' || event.key === '~' || event.key === '`') {
          event.preventDefault();
          panicNow();
        }
      });
      // Keep the crypt gate up until the game document actually paints,
      // then let the game's own loading screen take over.
      const started = performance.now();
      const check = () => {
        if (token !== state.loadToken) return;
        const inner = frame.contentDocument;
        const ready = inner && inner.readyState === 'complete' && inner.body && inner.body.childElementCount > 0;
        const elapsed = performance.now() - started;
        if ((ready && elapsed > 1000) || elapsed > 12000) hideLoader();
        else setTimeout(check, 200);
      };
      setTimeout(check, 400);
    } catch (error) {
      if (token !== state.loadToken) return;
      showError(`Couldn't load “${game.n}”. ${error && error.message ? `(${error.message})` : ''} The CDN may be asleep — try again or open it in a new tab.`);
    }
  }

  function openGame(game, { push = true } = {}) {
    if (!game) return;
    state.current = game;
    els.player.hidden = false;
    lockScroll();
    els.playerTitle.textContent = game.n;
    els.playerAuthor.textContent = game.a ? `by ${game.a}` : 'Unknown creator';
    els.playerThumb.src = coverUrl(game);
    els.playerThumb.alt = '';
    els.playerFav.classList.toggle('is-on', isFav(game.i));
    els.playerFav.setAttribute('aria-pressed', String(isFav(game.i)));
    pushRecent(game.i);
    if (push) {
      try {
        const url = new URL(window.location.href);
        url.searchParams.set('game', game.i);
        history.pushState({ game: game.i }, '', url);
      } catch (_) { /* file:// */ }
    }
    runGame(game);
    setTimeout(() => $('#playerBack')?.focus({ preventScroll: true }), 60);
  }

  let lockedScroll = 0;
  function lockScroll() {
    lockedScroll = window.scrollY || window.pageYOffset || 0;
    document.documentElement.classList.add('is-playing');
    document.body.style.top = `-${lockedScroll}px`;
  }

  function unlockScroll() {
    document.documentElement.classList.remove('is-playing');
    document.body.style.top = '';
    window.scrollTo(0, lockedScroll);
  }

  function closePlayer({ updateUrl = true } = {}) {
    if (els.player.hidden) return;
    state.loadToken += 1;
    els.player.hidden = true;
    unlockScroll();
    const frame = $('#gameFrame');
    if (frame) frame.src = 'about:blank';
    const current = state.current;
    state.current = null;
    if (updateUrl) {
      try {
        const url = new URL(window.location.href);
        url.searchParams.delete('game');
        history.replaceState(null, '', url);
      } catch (_) { /* ignore */ }
    }
    if (current) {
      const card = document.querySelector(`.card[data-id="${current.i}"]`);
      if (card) card.focus({ preventScroll: true });
    }
    if (document.fullscreenElement) document.exitFullscreen?.().catch(() => {});
  }

  async function openInNewTab() {
    if (!state.current) return;
    const game = state.current;
    if (isExternal(game)) {
      window.open(game.u, '_blank', 'noopener');
      return;
    }
    const win = window.open('about:blank', '_blank');
    if (!win) { toast('Pop-up blocked — allow pop-ups for this site.'); return; }
    try {
      const { html, url } = await fetchGame(game);
      win.document.open();
      win.document.write(withBase(html, url));
      win.document.close();
    } catch (_) {
      win.close();
      toast('Could not open that game in a new tab.');
    }
  }

  /* ---------------- toast ---------------- */

  let toastTimer = null;
  function toast(message) {
    els.toast.textContent = message;
    els.toast.classList.add('is-visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => els.toast.classList.remove('is-visible'), 2200);
  }

  /* ---------------- events ---------------- */

  els.filters.addEventListener('click', (event) => {
    const chip = event.target.closest('[data-filter]');
    if (!chip) return;
    setFilter(chip.dataset.filter);
  });

  els.sort.addEventListener('change', () => {
    state.sort = els.sort.value;
    refresh();
  });

  let searchTimer = null;
  els.search.addEventListener('input', () => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => {
      state.search = els.search.value.trim();
      buildList();
      renderGrid(true);
    }, 110);
  });

  els.search.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      els.search.value = '';
      state.search = '';
      buildList();
      renderGrid(true);
      els.search.blur();
    }
  });

  els.loadMore.addEventListener('click', () => {
    if (state.shown >= state.list.length) return;
    const previous = state.shown;
    state.shown = Math.min(state.shown + PAGE_SIZE, state.list.length);
    const slice = state.list.slice(previous, state.shown);
    const frag = document.createElement('div');
    frag.innerHTML = slice.map(cardHTML).join('');
    Array.from(frag.children).forEach((node) => els.grid.appendChild(node));
    bindImages(els.grid);
    els.moreWrap.hidden = state.shown >= state.list.length;
    els.resultCount.textContent = `${state.shown} of ${state.list.length} games shown`;
  });

  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries) => {
      if (entries.some((entry) => entry.isIntersecting)) {
        if (state.shown < state.list.length) els.loadMore.click();
      }
    }, { rootMargin: '900px 0px' });
    observer.observe(els.sentinel);
  }

  // card clicks, hearts, keyboard
  document.addEventListener('click', (event) => {
    const fav = event.target.closest('[data-fav]');
    if (fav) {
      event.preventDefault();
      event.stopPropagation();
      toggleFav(Number(fav.dataset.fav));
      return;
    }
    const link = event.target.closest('.card__link');
    if (link) {
      const card = link.closest('.card');
      const game = card && gameById.get(Number(card.dataset.id));
      if (game) {
        event.preventDefault();
        openGame(game);
      }
    }
  });

  document.addEventListener('keydown', (event) => {
    // No shortcuts while a panic screen is covering the arcade.
    const panicEl = document.getElementById('panic');
    if (panicEl && !panicEl.hidden) return;
    const typing = /^(input|textarea|select)$/i.test(event.target.tagName || '');
    const isTilde = event.code === 'Backquote' || event.key === '~' || event.key === '`';
    if (isTilde && !typing && !event.altKey) {
      // ~ fires the selected panic, Ctrl+~ toggles the tab cloak.
      event.preventDefault();
      if (event.ctrlKey || event.metaKey) toggleCloak();
      else panicNow();
      return;
    }
    if (event.key === '/' && !typing && !event.metaKey && !event.ctrlKey && !event.altKey) {
      event.preventDefault();
      els.search.focus();
      els.search.select();
      document.querySelector('#browse').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    if ((event.key === 'r' || event.key === 'R') && !typing && !event.metaKey && !event.ctrlKey && !event.altKey && els.player.hidden) {
      playRandom();
    }
    if (event.key === 'Escape') {
      if (!els.player.hidden) closePlayer();
      else if (document.activeElement === els.search) els.search.blur();
    }
  });

  // pointer glow on cards
  let glowFrame = null;
  document.addEventListener('pointermove', (event) => {
    const card = event.target.closest && event.target.closest('.card');
    if (!card || glowFrame) return;
    glowFrame = requestAnimationFrame(() => {
      const rect = card.getBoundingClientRect();
      card.style.setProperty('--mx', `${event.clientX - rect.left}px`);
      card.style.setProperty('--my', `${event.clientY - rect.top}px`);
      glowFrame = null;
    });
  }, { passive: true });

  $('#randomBtn').addEventListener('click', playRandom);
  $('#footerRandom').addEventListener('click', playRandom);
  $('#searchJump').addEventListener('click', () => {
    els.search.focus();
    $('#browse').scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  $$('[data-genre]').forEach((link) => {
    link.addEventListener('click', (event) => {
      event.preventDefault();
      setFilter(link.dataset.genre, { scroll: true });
    });
  });

  $('#spotPlay').addEventListener('click', () => openGame(currentSpotlight()));
  $('#spotFav').addEventListener('click', () => {
    const game = currentSpotlight();
    if (game) toggleFav(game.i);
  });
  $('#heroPlay').addEventListener('click', () => openGame(currentSpotlight()));
  els.spotDots.addEventListener('click', (event) => {
    const dot = event.target.closest('[data-spot]');
    if (dot) renderSpotlight(Number(dot.dataset.spot));
  });
  const spot = $('#spotlight');
  spot.addEventListener('pointerenter', () => clearInterval(spotTimer));
  spot.addEventListener('pointerleave', restartSpotTimer);

  $('#clearRecent').addEventListener('click', () => {
    state.recent = [];
    storage.write(RECENT_KEY, []);
    renderRecent();
    toast('Play history cleared');
  });

  $('#footerClear').addEventListener('click', () => {
    state.recent = [];
    state.favourites = new Set();
    storage.write(RECENT_KEY, []);
    storage.write(FAV_KEY, []);
    renderRecent();
    refresh();
    toast('Local data cleared');
  });

  $('#playerBack').addEventListener('click', () => closePlayer());
  $('#playerClose').addEventListener('click', () => closePlayer());
  $('#playerReload').addEventListener('click', () => { if (state.current) runGame(state.current); });
  $('#playerNewTab').addEventListener('click', openInNewTab);
  $('#errorNewTab').addEventListener('click', openInNewTab);
  $('#errorRetry').addEventListener('click', () => { if (state.current) runGame(state.current); });
  $('#playerFav').addEventListener('click', () => { if (state.current) toggleFav(state.current.i); });
  $('#playerFullscreen').addEventListener('click', () => {
    if (!document.fullscreenElement) {
      els.player.requestFullscreen?.().catch(() => toast('Fullscreen is not available here.'));
    } else {
      document.exitFullscreen?.().catch(() => {});
    }
  });

  $('#resetFilters').addEventListener('click', () => {
    state.search = '';
    els.search.value = '';
    els.sort.value = 'featured';
    state.sort = 'featured';
    setFilter('all');
  });

  window.addEventListener('popstate', () => {
    const id = new URLSearchParams(window.location.search).get('game');
    if (id != null && gameById.has(Number(id))) openGame(gameById.get(Number(id)), { push: false });
    else closePlayer({ updateUrl: false });
  });

  /* ---------------- 5-second panic screens ---------------- */

  // Purely visual decoys: no inputs, no credential handling, no network calls.
  // Any click (or Esc) reveals the arcade early; otherwise it lifts after 5s.
  function initPanic() {
    const panic = document.getElementById('panic');
    if (!panic) return;

    const tab = window.__panicTab;
    const panes = Array.from(panic.querySelectorAll('[data-panic-pane]'));
    const background = Array.from(document.body.children).filter((el) => el !== panic && el.tagName !== 'SCRIPT');

    let timer = null;
    let hidden = true;
    let current = null;

    const setInert = (value) => {
      background.forEach((el) => { el.inert = value; });
    };

    const hide = () => {
      if (hidden) return;
      hidden = true;
      clearTimeout(timer);
      panic.classList.add('is-out');
      if (tab) tab.restore();
      document.documentElement.removeAttribute('data-panic');
      setTimeout(() => {
        if (!hidden) return;
        panic.hidden = true;
        panic.setAttribute('aria-hidden', 'true');
        setInert(false);
      }, 420);
    };

    const show = (kind) => {
      const pane = panes.find((p) => p.dataset.panicPane === kind);
      if (!pane) return false;
      panes.forEach((p) => p.classList.toggle('is-on', p === pane));
      current = kind;
      hidden = false;
      panic.hidden = false;
      panic.setAttribute('aria-hidden', 'false');
      panic.classList.remove('is-out');
      document.documentElement.dataset.panic = kind;
      setInert(true);
      if (tab) tab.apply(kind);
      clearTimeout(timer);
      timer = setTimeout(hide, PANIC_MS);
      return true;
    };

    panicApi = { show, hide, current: () => current };

    // A page-tab switch is not a fresh visit, so the boot script skipped the
    // decoy; "none" matches no pane and leaves the arcade straight up.
    const wanted = tab && tab.skipped ? 'none' : (tab ? tab.get() : 'schoology');
    if (!show(wanted)) { panic.hidden = true; setInert(false); }

    // Esc always lifts the panic — useful when it comes back after "Panic now".
    document.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape' || hidden) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      hide();
    }, true);

    panic.addEventListener('click', (event) => {
      // Links inside the decoy should never navigate anywhere real.
      const link = event.target.closest('a');
      if (link) event.preventDefault();
      hide();
    });
  }

  /* ---------------- panic + cloak shortcuts ---------------- */

  function panicNow() {
    const kind = window.__panicTab ? window.__panicTab.get() : 'schoology';
    if (kind === 'none' || !panicApi) {
      toast('Pick a panic screen in the menu first.');
      return;
    }
    if (closeMenuHook) closeMenuHook();
    panicApi.show(kind);
  }

  function toggleCloak() {
    const cloak = window.__ghoulCloak;
    if (!cloak) return;
    cloak.setOn(!cloak.on());
    if (syncCloakToggle) syncCloakToggle();
    toast(cloak.on()
      ? `Tab cloaked as ${designLabel(cloak.design())}.`          : 'Cloak off — the tab is Ghoulish again.');
  }

  /* ---------------- theme, panic and cloak settings ---------------- */

  const ACCENTS = [
    { id: 'blood', name: 'Blood', hex: '#e0142b' },
    { id: 'venom', name: 'Venom', hex: '#38d94a' },
    { id: 'abyss', name: 'Abyss', hex: '#2f9bff' },
    { id: 'amethyst', name: 'Amethyst', hex: '#a86bff' },
    { id: 'ember', name: 'Ember', hex: '#ff7a1a' },
    { id: 'frost', name: 'Frost', hex: '#8fe3ff' }
  ];

  const PANIC_CHOICES = [
    { id: 'schoology', label: 'Schoology' },
    { id: 'classroom', label: 'Classroom' },
    { id: 'drive', label: 'Drive' },
    { id: 'search', label: 'Google' },
    { id: 'none', label: 'None' }
  ];

  const CLOAK_CHOICES = PANIC_CHOICES.filter((choice) => choice.id !== 'none');

  const designLabel = (id) => (PANIC_CHOICES.find((c) => c.id === id) || { label: 'Ghoulish' }).label;

  function initSettings() {
    const theme = window.__ghoulTheme;
    const tab = window.__panicTab;
    const menu = $('#menu');
    const button = $('#menuBtn');
    if (!menu || !button) return;

    /* accent swatches */
    const swatches = $('#swatches');
    const custom = $('#accentCustom');
    const activeAccent = () => (theme && theme.current ? theme.current().toLowerCase() : '#e0142b');

    const markAccent = (hex) => {
      const wanted = String(hex || '').toLowerCase();
      $$('.swatch', swatches).forEach((dot) => {
        dot.classList.toggle('is-on', dot.dataset.hex.toLowerCase() === wanted);
      });
      if (custom && /^#[0-9a-f]{6}$/i.test(wanted)) custom.value = wanted;
    };

    ACCENTS.forEach((accent) => {
      const dot = document.createElement('button');
      dot.type = 'button';
      dot.className = 'swatch';
      dot.dataset.hex = accent.hex;
      dot.style.background = accent.hex;
      dot.title = accent.name;
      dot.setAttribute('aria-label', `${accent.name} accent`);
      dot.addEventListener('click', () => {
        if (theme) theme.apply(accent.hex);
        markAccent(accent.hex);
      });
      swatches.appendChild(dot);
    });
    markAccent(activeAccent());

    custom?.addEventListener('input', () => {
      if (theme) theme.apply(custom.value);
      markAccent(custom.value);
    });

    /* look & feel: font, shape, density, atmosphere, motion */
    const lookSyncers = [];

    function buildPicker(container, choices, key) {
      if (!container) return;
      container.innerHTML = '';
      const nodes = choices.map((choice) => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'chip';
        chip.dataset.value = choice.id;
        chip.textContent = choice.label;
        chip.addEventListener('click', () => setLook({ [key]: choice.id }));
        container.appendChild(chip);
        return chip;
      });
      lookSyncers.push(() => nodes.forEach((chip) => {
        const on = String(state.look[key]) === chip.dataset.value;
        chip.classList.toggle('is-on', on);
        chip.setAttribute('aria-pressed', String(on));
      }));
    }

    function syncLookFields() {
      if (nameInput) nameInput.value = state.look.name || '';
      if (taglineInput) taglineInput.value = state.look.tagline || '';
      if (bgInput) bgInput.value = state.look.bg || '';
    }

    function applyLookState() {
      applyLook();
      applyBranding();
      lookSyncers.forEach((sync) => sync());
      syncLookFields();
    }

    function setLook(patch) {
      state.look = { ...state.look, ...patch };
      writeLook();
      applyLookState();
    }

    buildPicker($('#fontPicker'), [
      { id: 'cinzel', label: 'Cinzel' },
      { id: 'grotesk', label: 'Grotesk' },
      { id: 'serif', label: 'Serif' },
      { id: 'mono', label: 'Mono' }
    ], 'font');
    buildPicker($('#cornerPicker'), [
      { id: 'round', label: 'Rounded' },
      { id: 'sharp', label: 'Sharp' }
    ], 'corners');
    buildPicker($('#densityPicker'), [
      { id: 'compact', label: 'Compact' },
      { id: 'cozy', label: 'Cozy' },
      { id: 'large', label: 'Large' }
    ], 'density');
    buildPicker($('#ambiencePicker'), [
      { id: 'full', label: 'Full' },
      { id: 'calm', label: 'Calm' },
      { id: 'off', label: 'Off' }
    ], 'ambience');
    buildPicker($('#motionPicker'), [
      { id: 'on', label: 'On' },
      { id: 'off', label: 'Off' }
    ], 'motion');

    /* home section toggles */
    const homePicker = $('#homePicker');
    const HOME_CHOICES = [
      { id: 'spotlight', label: 'Featured' },
      { id: 'recent', label: 'Recently played' },
      { id: 'how', label: 'How it works' }
    ];
    if (homePicker) {
      homePicker.innerHTML = '';
      const homeChips = HOME_CHOICES.map((choice) => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'chip';
        chip.dataset.home = choice.id;
        chip.textContent = choice.label;
        chip.addEventListener('click', () => setLook({ [choice.id]: !state.look[choice.id] }));
        homePicker.appendChild(chip);
        return chip;
      });
      lookSyncers.push(() => homeChips.forEach((chip) => {
        const on = Boolean(state.look[chip.dataset.home]);
        chip.classList.toggle('is-on', on);
        chip.setAttribute('aria-pressed', String(on));
      }));
    }

    /* branding fields */
    const nameInput = $('#brandNameInput');
    const taglineInput = $('#brandTaglineInput');
    const bgInput = $('#bgImageInput');

    if (nameInput) {
      nameInput.addEventListener('input', () => {
        state.look.name = nameInput.value.slice(0, 18);
        writeLook();
        applyBranding();
      });
    }
    if (taglineInput) {
      taglineInput.addEventListener('input', () => {
        state.look.tagline = taglineInput.value.slice(0, 70);
        writeLook();
        applyBranding();
      });
    }
    let bgTimer = null;
    const commitBg = () => {
      const typed = bgInput ? bgInput.value.trim() : '';
      const url = safeImageUrl(typed);
      if (typed && !url) {
        toast('That backdrop URL is not allowed.');
        if (bgInput) bgInput.value = state.look.bg || '';
        return;
      }
      state.look.bg = url;
      writeLook();
      applyLook();
    };
    if (bgInput) {
      bgInput.addEventListener('input', () => {
        clearTimeout(bgTimer);
        bgTimer = setTimeout(commitBg, 500);
      });
      bgInput.addEventListener('change', () => {
        clearTimeout(bgTimer);
        commitBg();
      });
    }

    $('#resetLook')?.addEventListener('click', () => {
      state.look = { ...LOOK_DEFAULTS };
      try { localStorage.removeItem(LOOK_KEY); } catch (_) {}
      if (theme) theme.apply(theme.DEFAULT || '#e0142b');
      markAccent(theme && theme.DEFAULT ? theme.DEFAULT : '#e0142b');
      applyLookState();
      toast('Appearance reset to the crypt default.');
    });

    lookSyncers.forEach((sync) => sync());
    syncLookFields();

    /* panic chips */
    const picker = $('#panicPicker');
    const markPanic = (kind) => {
      $$('.chip', picker).forEach((chip) => chip.classList.toggle('is-on', chip.dataset.kind === kind));
      $$('.chip', picker).forEach((chip) => chip.setAttribute('aria-pressed', String(chip.dataset.kind === kind)));
    };

    PANIC_CHOICES.forEach((choice) => {
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'chip';
      chip.dataset.kind = choice.id;
      chip.textContent = choice.label;
      chip.setAttribute('aria-pressed', 'false');
      chip.addEventListener('click', () => {
        if (tab) tab.set(choice.id);
        markPanic(choice.id);
        toast(choice.id === 'none'
          ? 'Panic off — press ~ and nothing happens.'
          : `${choice.label} panic set. Press ~ any time.`);
      });
      picker.appendChild(chip);
    });
    markPanic(tab ? tab.get() : 'schoology');

    $('#panicNow')?.addEventListener('click', () => {
      closeMenu();
      panicNow();
    });

    /* cloak chips + toggle (tab title and favicon only) */
    const cloak = window.__ghoulCloak;
    if (cloak) {
      const cloakPicker = $('#cloakPicker');
      const toggle = $('#cloakToggle');

      const markCloak = (kind) => {
        $$('.chip', cloakPicker).forEach((chip) => {
          chip.classList.toggle('is-on', chip.dataset.kind === kind);
          chip.setAttribute('aria-pressed', String(chip.dataset.kind === kind));
        });
      };

      CLOAK_CHOICES.forEach((choice) => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'chip';
        chip.dataset.kind = choice.id;
        chip.textContent = choice.label;
        chip.addEventListener('click', () => {
          cloak.setDesign(choice.id);
          markCloak(choice.id);
          if (cloak.on()) toast(`Tab cloaked as ${choice.label}.`);
        });
        cloakPicker.appendChild(chip);
      });
      markCloak(cloak.design());

      syncCloakToggle = () => {
        const on = cloak.on();
        toggle.textContent = on ? 'Cloak tab: on' : 'Cloak tab: off';
        toggle.setAttribute('aria-pressed', String(on));
      };
      syncCloakToggle();

      toggle.addEventListener('click', () => {
        cloak.setOn(!cloak.on());
        syncCloakToggle();
        toast(cloak.on()
          ? `Tab cloaked as ${designLabel(cloak.design())}.`
        : 'Cloak off — the tab is Ghoulish again.');
    });
    }

    /* open / close */
    function openMenu() {
      menu.hidden = false;
      button.setAttribute('aria-expanded', 'true');
      document.addEventListener('pointerdown', onOutside, true);
      document.addEventListener('keydown', onMenuKey, true);
    }

    function closeMenu() {
      if (menu.hidden) return;
      menu.hidden = true;
      button.setAttribute('aria-expanded', 'false');
      document.removeEventListener('pointerdown', onOutside, true);
      document.removeEventListener('keydown', onMenuKey, true);
    }

    function onOutside(event) {
      if (menu.contains(event.target) || button.contains(event.target)) return;
      closeMenu();
    }

    function onMenuKey(event) {
      if (event.key !== 'Escape') return;
      closeMenu();
      button.focus();
    }

    closeMenuHook = closeMenu;

    button.addEventListener('click', () => {
      if (menu.hidden) openMenu();
      else closeMenu();
    });
    $('#menuClose')?.addEventListener('click', () => { closeMenu(); button.focus(); });
    $('.menu__github', menu)?.addEventListener('click', closeMenu);
  }

  /* ---------------- misc ---------------- */

  function playRandom() {
    const pool = state.list.length ? state.list : GAMES;
    if (!pool.length) return;
    const game = pool[Math.floor(Math.random() * pool.length)];
    openGame(game);
  }

  /* The page tabs stay plain links, so they still work without JS. Switching
     stamps sessionStorage just before the navigation: the boot script reads it
     and skips that load's decoy, since the arcade was already open. */
  function initPageTabs() {
    $$('[data-page]').forEach((tab) => {
      tab.addEventListener('click', (event) => {
        if (event.defaultPrevented || event.button !== 0) return;
        if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
        // Clicking the page you are already on is a reload, decoy and all.
        if (tab.dataset.page === PAGE_ID) return;
        try { sessionStorage.setItem('ghoul:pageJump', String(Date.now())); } catch (err) {}
      });
    });
  }

  function initPageChrome() {
    const baseTitle = typeof LIB.title === 'function' ? LIB.title(GAMES.length) : LIB.title;
    state.baseTitle = baseTitle;
    const name = siteName();
    const title = baseTitle.replace(/Ghoulish/g, name);
    const description = (typeof LIB.description === 'function' ? LIB.description(GAMES.length) : LIB.description)
      .replace(/Ghoulish/g, name);
    if (window.__panicTab && window.__panicTab.setPageTitle) window.__panicTab.setPageTitle(title);
    else document.title = title;
    $('meta[name="description"]')?.setAttribute('content', description);
    $('meta[property="og:title"]')?.setAttribute('content', title);
    $('meta[property="og:description"]')?.setAttribute('content', description);

    $$('[data-page]').forEach((tab) => {
      const active = tab.dataset.page === PAGE_ID;
      tab.classList.toggle('is-active', active);
      if (active) tab.setAttribute('aria-current', 'page');
      else tab.removeAttribute('aria-current');
    });

    // Both catalogues are loaded, so each tab can show its real total.
    $$('[data-page-count]').forEach((node) => {
      const library = LIBRARIES[node.dataset.pageCount];
      const catalogue = library && window[library.catalogue];
      if (Array.isArray(catalogue)) node.textContent = `${catalogue.length} games`;
    });

    // Genre shortcuts that this page has nothing for would dead-end.
    const shelves = new Set(GAMES.flatMap((g) => g.g || []));
    $$('[data-genre]').forEach((link) => {
      const genre = link.dataset.genre;
      link.hidden = !(genre === 'all' || genre === 'favorites' || shelves.has(genre));
    });

    const set = (selector, text) => {
      const node = $(selector);
      if (node) node.textContent = text;
    };
    set('#heroEyebrow', LIB.eyebrow);
    set('#heroLede', LIB.lede);
    set('#browseEyebrow', LIB.browseEyebrow);
    set('#browseLink', LIB.browseLink);
    set('#howCount', `${GAMES.length} and counting`);

    const catalogueLink = $('#catalogueLink');
    if (catalogueLink) {
      catalogueLink.href = LIB.repo[0];
      catalogueLink.textContent = LIB.repo[1];
    }
  }

  function init() {
    initPageTabs();
    if (!GAMES.length) {
      els.resultCount.textContent = 'The catalogue failed to load.';
      return;
    }
    applyLook();
    initSettings();
    initPageChrome();
    applyBranding();

    $('#statGames').textContent = GAMES.length;
    $('#statGenres').textContent = new Set(GAMES.flatMap((g) => g.g || [])).size;
    els.search.placeholder = `Search ${GAMES.length} games…`;
    $('#year').textContent = new Date().getFullYear();

    refresh();
    renderRecent();
    renderSpotlight(0);

    const params = new URLSearchParams(window.location.search);
    const genre = params.get('genre');
    if (genre && FILTERS.some((f) => f.id === genre)) setFilter(genre);
    const id = params.get('game');
    if (id != null && gameById.has(Number(id))) openGame(gameById.get(Number(id)), { push: false });
  }

  init();
})();
